import React,{useState} from 'react';
import {NavLink, Link} from 'react-router-dom';
import {AnimatePresence,motion} from 'framer-motion';
import Icon from './Icon';

export function Logo(){return <Link className="brand" to="/" aria-label="Beyond31 accueil"><img src="/images/beyond31_logo.png" alt=""/><span>Beyond31</span></Link>}

const nav=[['/','home','Accueil'],['/projets','work','Projets'],['/expertise','code','Compétences'],['/studio','studio','Vision']];

export default function Layout({children}){
 const [open,setOpen]=useState(false);
 return <div className="shell">
  <header className="topbar">
    <Logo/>
    <nav className="nav-glass" aria-label="Navigation principale">
      {nav.map(([to,icon,label])=><NavLink key={to} to={to} end={to==='/' }><Icon name={icon}/><span>{label}</span></NavLink>)}
    </nav>
    <Link className="contact-pill" to="/contact"><span>Écrire</span><Icon name="arrow" size={16}/></Link>
    <button className="menu-toggle" onClick={()=>setOpen(!open)} aria-expanded={open}>{open?'Fermer':'Menu'}</button>
  </header>
  <AnimatePresence>{open&&<motion.div className="menu-panel" initial={{opacity:0,y:-12}} animate={{opacity:1,y:0}} exit={{opacity:0,y:-12}}>{[...nav,['/contact','contact','Contact']].map(([to,icon,label])=><NavLink onClick={()=>setOpen(false)} key={to} to={to}><Icon name={icon}/><span>{label}</span><Icon name="arrow"/></NavLink>)}</motion.div>}</AnimatePresence>
  <main>{children}</main>
  <footer className="footer">
    <div className="footer-main"><Logo/><p>Aller plus loin que la limite attendue.</p></div>
    <div className="footer-links"><Link to="/projets">Projets</Link><Link to="/expertise">Compétences</Link><Link to="/studio">Vision</Link><Link to="/contact">Contact</Link></div>
    <div className="footer-meta"><span>Huriel Nguimbi · Poitiers</span><a href="mailto:contact@beyond31.online">contact@beyond31.online</a><div><Link to="/mentions-legales">Mentions légales</Link><Link to="/confidentialite">Confidentialité</Link></div></div>
  </footer>
 </div>
}
